/* STEP 2 - Prefix Master rows for the Cogxim sale import (run once on BAPLDMSvad, after STEP 1).
   Creates one "Vehicle Sale Bill" (sale_bill) prefix per dealer per financial year that has Cogxim sales:
       VSB/<last 3 digits of dealer code>/<FY>/###      e.g. VSB/005/20-21/###
   - Skipped when the dealer already has a sale_bill prefix for that year (yours are kept and used).
   - Old years are created INACTIVE (the import uses them by Year; live billing is not affected).
   - 26-27 is created ACTIVE only for dealers that have no active sale_bill prefix at all.
   - Rows are inserted newest year first, so a dealer's first row is the current year.
   - NextNo starts at 1; the import moves it past the last number it uses, so after the import
     Prefix Master shows where each year's series stopped.
   Dealers not present in DealerMaster are skipped. */
USE [BAPLDMSvad];
GO
SET NOCOUNT ON;
DECLARE @Need TABLE (DealerCode NVARCHAR(50), FY NVARCHAR(10), Ord INT IDENTITY(1,1));

DECLARE @Format NVARCHAR(200) = COALESCE(
    (SELECT TOP 1 Format FROM dbo.NumberSequence WHERE SequenceName = 'sale_bill' AND SequenceCode LIKE 'VSB/%' ORDER BY Id DESC),
    (SELECT TOP 1 Format FROM dbo.NumberSequence WHERE SequenceName = 'sale_bill' ORDER BY Id DESC),
    '###');

BEGIN TRAN;

SELECT 'VSB/' + RIGHT(n.DealerCode, 3) + '/' + n.FY + '/###', 'sale_bill', @Format, 1, 1, n.DealerCode, n.FY,
       CASE WHEN n.FY = '26-27' AND NOT EXISTS (SELECT 1 FROM dbo.NumberSequence a
                                                WHERE a.DealerCode = n.DealerCode AND a.SequenceName = 'sale_bill' AND a.IsActive = 1)
            THEN 1 ELSE 0 END,
       NULL, 'Cogxim Import', GETDATE()
FROM @Need n
WHERE EXISTS (SELECT 1 FROM dbo.DealerMaster dm WHERE dm.Dealercode = n.DealerCode)
  AND NOT EXISTS (SELECT 1 FROM dbo.NumberSequence x
                  WHERE x.DealerCode = n.DealerCode AND x.SequenceName = 'sale_bill' AND LTRIM(RTRIM(x.[Year])) = n.FY)
ORDER BY n.Ord;

SELECT @@ROWCOUNT AS PrefixRowsCreated;   -- check, then COMMIT (or ROLLBACK)

COMMIT TRAN;
GO

