/* Prefix rows per year */
SELECT [Year], COUNT(*) AS Prefixes, SUM(CASE WHEN IsActive = 1 THEN 1 ELSE 0 END) AS Active
FROM dbo.NumberSequence WHERE SequenceName = 'sale_bill' GROUP BY [Year] ORDER BY [Year];
